124	        }
125	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
126	    }
127	
128	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
129	    @Override
130	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
131	        Owner owner = this.clinicService.findOwnerById(ownerId);
132	        if (owner == null) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
141	        List<String> missingFields = new ArrayList<>();
142	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
143	            missingFields.add("firstName");
144	        }
145	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
146	            missingFields.add("lastName");
147	        }
148	        // Normalize the address up front; the required-field check rejects it when it is blank
149	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
150	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
151	        if (!StringUtils.hasText(normalizedAddress)) {
152	            missingFields.add("address");
153	        }
154	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
155	            missingFields.add("city");
156	        }
157	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
158	            missingFields.add("telephone");
159	        }
160	        if (!missingFields.isEmpty()) {
161	            throw new InvalidRequestException(missingFields);
162	        }
163	        HttpHeaders headers = new HttpHeaders();
164	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
165	        // Store (and later return) the normalized address computed above.
166	        owner.setAddress(normalizedAddress);
167	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
168	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
169	        owner.setTelephone(normalizedTelephone);
170	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
171	        owner.setEmail(normalizeEmail(owner.getEmail()));
172	        // Default the (optional) registration date to the server's current date when none was supplied.
173	        if (owner.getRegistrationDate() == null) {
174	            owner.setRegistrationDate(LocalDate.now());
175	        }
176	        // Reject the request when the owner's city has already reached its owner capacity.
177	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
178	            throw new CityCapacityException(owner.getCity());
179	        }
180	        // Reject the request if the E.164 telephone is already used by another owner.
181	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
182	            throw new DuplicateTelephoneException(normalizedTelephone);
183	        }
184	        // Reject the request if another owner already shares the same last name and address
185	        // (compared case-insensitively with collapsed whitespace), unless the caller opts in
186	        // by setting 'sharesHousehold' true. When they do opt in and an existing household is
187	        // matched, assign a stable shared 'householdId' to the new owner and backfill it onto
188	        // every existing member that does not yet carry it.
189	        List<Owner> householdMembers = findHouseholdMembers(owner.getLastName(), owner.getAddress());
190	        if (!householdMembers.isEmpty()) {
191	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
192	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
193	            }
194	            String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
195	            owner.setHouseholdId(householdId);
196	            for (Owner member : householdMembers) {
197	                if (!householdId.equals(member.getHouseholdId())) {
198	                    member.setHouseholdId(householdId);
199	                    this.clinicService.saveOwner(member);
200	                }
201	            }
202	        }
203	        // Record how many existing owners already share this first name and last name
204	        // (compared case-insensitively) before this owner is created.
205	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
206	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' before persisting.
207	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
208	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
209	        // digits of the registration date year (e.g. 'SYD-SMI-0007-M26').
210	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
211	        this.clinicService.saveOwner(owner);
212	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
213	        headers.setLocation(UriComponentsBuilder.newInstance()
214	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
215	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
216	    }
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
221	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
222	        if (currentOwner == null) {
223	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
224	        }
225	        currentOwner.setAddress(ownerFieldsDto.getAddress());
226	        currentOwner.setCity(ownerFieldsDto.getCity());
227	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
228	        currentOwner.setLastName(ownerFieldsDto.getLastName());
229	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
230	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
231	        this.clinicService.saveOwner(currentOwner);
232	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
233	    }
234	
235	    /**
236	     * Generate a customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3} is the
237	     * upper-cased first three letters of {@code city}, {@code LAST3} is the upper-cased first three
238	     * letters of {@code lastName} and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to
239	     * one more than the current number of owners already in that city (e.g. {@code SYD-SMI-0007}).
240	     *
241	     * @param city     the owner's city
242	     * @param lastName the owner's last name
243	     * @return the generated customer code
244	     */
245	    private String generateCustomerCode(String city, String lastName) {
246	        String cityPrefix = city.length() >= 3 ? city.substring(0, 3) : city;
247	        String lastPrefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
248	        String normalizedCity = normalizeForComparison(city);
249	        int sequence = (int) this.clinicService.findAllOwners().stream()
250	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
251	            .count() + 1;
252	        return String.format("%s-%s-%04d", cityPrefix.toUpperCase(Locale.ROOT),
253	            lastPrefix.toUpperCase(Locale.ROOT), sequence);
254	    }
255	
256	    /**
257	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
258	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
259	     *
260	     * @param customerCode     the owner's already-assigned customer code
261	     * @param registrationDate the owner's registration date
262	     * @return the generated membership number
263	     */
264	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
265	        String yy = String.format("%02d", registrationDate.getYear() % 100);
266	        return String.format("%s-M%s", customerCode, yy);
267	    }
268	
269	    /**
270	     * Count the existing owners that share the given first name and last name, comparing each
271	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
272	     * yet persisted, so it is not included in the count.
273	     *
274	     * @param firstName the incoming owner's first name
275	     * @param lastName  the incoming owner's last name
276	     * @return the number of existing namesakes
277	     */
278	    private int countNamesakes(String firstName, String lastName) {
279	        String normalizedFirstName = normalizeForComparison(firstName);
280	        String normalizedLastName = normalizeForComparison(lastName);
281	        return (int) this.clinicService.findAllOwners().stream()
282	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
283	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
284	            .count();
285	    }
286	
287	    /**
288	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
289	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
290	     *
291	     * @param city the incoming owner's city
292	     * @return the number of existing owners already in that city
293	     */
294	    private int countOwnersInCity(String city) {
295	        String normalizedCity = normalizeForComparison(city);
296	        return (int) this.clinicService.findAllOwners().stream()
297	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
298	            .count();
299	    }
300	
301	    /**
302	     * Find the existing owners that live in the same household as the given values, i.e. those that
303	     * share both the last name and the address when each is compared case-insensitively with
304	     * collapsed whitespace.
305	     *
306	     * @param lastName the incoming owner's last name
307	     * @param address  the incoming owner's address
308	     * @return the matching existing owners (possibly empty)
309	     */
310	    private List<Owner> findHouseholdMembers(String lastName, String address) {
311	        String normalizedLastName = normalizeForComparison(lastName);
312	        String normalizedAddress = normalizeForComparison(address);
313	        return this.clinicService.findAllOwners().stream()
314	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
315	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
316	            .toList();
317	    }
318	
319	    /**
320	     * Generate a stable shared household identifier for the given last name and address. The value is
321	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
322	     * and address, so every owner joining the same household resolves to the same identifier. It is the
323	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
324	     *
325	     * @param lastName the household's last name
326	     * @param address  the household's address
327	     * @return the stable household identifier
328	     */
329	    private String generateHouseholdId(String lastName, String address) {
330	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
331	        try {
332	            byte[] digest = MessageDigest.getInstance("SHA-256")
333	                .digest(key.getBytes(StandardCharsets.UTF_8));
334	            StringBuilder sb = new StringBuilder(digest.length * 2);
335	            for (byte b : digest) {
336	                sb.append(String.format("%02x", b));
337	            }
338	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
339	        } catch (java.security.NoSuchAlgorithmException e) {
340	            throw new IllegalStateException("SHA-256 not available", e);
341	        }
342	    }
343	
344	    /**
345	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
346	     * single space, upper-case the result and expand common street-type abbreviations token by token
347	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
348	     * to the empty string. The result is the canonical form that is stored, returned and used for every
349	     * address comparison (household duplicate detection and the shared household id).
350	     *
351	     * @param address the raw address, may be {@code null}
352	     * @return the normalized address
353	     */
354	    private String normalizeAddress(String address) {
355	        if (address == null) {
356	            return "";
357	        }
358	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
359	        if (collapsed.isEmpty()) {
360	            return "";
361	        }
362	        String[] tokens = collapsed.split(" ");
363	        StringBuilder sb = new StringBuilder(collapsed.length());
364	        for (int i = 0; i < tokens.length; i++) {
365	            if (i > 0) {
366	                sb.append(' ');
367	            }
368	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
369	        }
370	        return sb.toString();
371	    }
372	
373	    /**
374	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
375	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
376	     *
377	     * @param value the raw value, may be {@code null}
378	     * @return the normalized value
379	     */
380	    private String normalizeForComparison(String value) {
381	        if (value == null) {
382	            return "";
383	        }
384	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
385	    }
386	
387	    /**
388	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
389	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
390	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
391	     * is returned lower-cased.
392	     *
393	     * @param email the raw email from the request payload, may be {@code null}
394	     * @return the lower-cased email, or {@code null} when none was provided
395	     */
396	    private String normalizeEmail(String email) {
397	        if (!StringUtils.hasText(email)) {
398	            return null;
399	        }
400	        if (!EMAIL_PATTERN.matcher(email).matches()) {
401	            throw new InvalidRequestException(List.of("email"));
402	        }
403	        return email.toLowerCase(Locale.ROOT);
404	    }
405	
406	    /**
407	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
408	     * already carries a leading '+' keeps its country code; otherwise the default country code
409	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
410	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
411	     * is thrown (mapped to 400 Bad Request).
412	     *
413	     * @param telephone the raw telephone from the request payload
414	     * @return the E.164 string (e.g. {@code +61412345678})
415	     */
416	    private String normalizeTelephone(String telephone) {
417	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
418	        String candidate;
419	        if (cleaned.startsWith("+")) {
420	            candidate = cleaned;
421	        } else {
422	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
423	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
424	        }
425	        if (!E164_PATTERN.matcher(candidate).matches()) {
426	            throw new InvalidRequestException(List.of("telephone"));
427	        }
428	        return candidate;
429	    }
430	
431	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
